// AURACLE — a full instrument. Main thread: app frame (PLAY/EVOLVE/TASTE),
// patch bank, the interactive rack, taste instruments, and the live keyboard
// (AudioWorklet synthesis via live-audio.js). All engine compute (rendering,
// MCMC, evolution) lives in worker.js; candidates are addressed by stable id.

const $ = (id) => document.getElementById(id);
const SVG_NS = "http://www.w3.org/2000/svg";

// Canvas and SVG attributes have no access to CSS custom properties, so the
// painted surfaces (scopes, taste map, lineage, the rack's defs) read the token
// layer through `tok`, once per name. Every colour comes from
// www/brand/tokens.json by way of style.css, or the painted surfaces drift
// away from the styled ones every time the palette moves; `make dev-check`
// fails on a colour written here.
const TOKENS = new Map();
function tok(name) {
  let v = TOKENS.get(name);
  if (v === undefined) {
    v = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
    if (v) TOKENS.set(name, v);
  }
  return v;
}
const INK = {
  silk: tok("--silk"),
  silkDim: tok("--silk-dim"),
  green: tok("--phos-a"),
  greenDim: tok("--phos-a-dim"),
  amber: tok("--phos-b"),
  amberDim: tok("--phos-b-dim"),
  amberDeep: tok("--phos-b-deep"),
};
// Canvas text is set at the canvas floor, `--t-canvas` (12 px; TA20 found the
// 10 px it had too small), in the mono family, scaled by the pixel ratio. A
// canvas cannot read a custom property, and `make dev-check` counts a size
// written into a `.font` string here.
const CANVAS_PX = parseFloat(tok("--t-canvas"));
const canvasFont = (dpr) => `${CANVAS_PX * dpr}px ${tok("--font-mono")}`;
// A motion token's length in ms (`--d-press`, `--d-state`, `--d-move`,
// `--d-zoom`), read when a motion starts rather than once: the reduced-motion
// rule sets them to 0, and the setting can change with the app open. A
// script's tween takes its length here, so it keeps the same four speeds, and
// the same rule, as a CSS transition; `make dev-check` counts an animation's
// literal `duration:`.
const motionMs = (name) => parseFloat(getComputedStyle(document.documentElement).getPropertyValue(name)) || 0;
// Two phosphors and silk, and nothing else: every other colour the canvases
// and the inline styles use is made *from* these tokens, so no third hue can
// creep in as a literal and the whole instrument moves when the palette does.
const inkRgb = (hex) => {
  const m = /^#?([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(String(hex).trim());
  return m ? [parseInt(m[1], 16), parseInt(m[2], 16), parseInt(m[3], 16)] : null;
};
// A token at an opacity (`inkAlpha(INK.amber, 0.05)`), for washes and trails.
function inkAlpha(hex, a) {
  const c = inkRgb(hex);
  return c ? `rgba(${c[0]}, ${c[1]}, ${c[2]}, ${a})` : hex;
}
// A token `t` of the way toward another, as hex: shades between two inks.
function inkMix(a, b, t) {
  const x = inkRgb(a);
  const y = inkRgb(b);
  if (!x || !y) return a;
  return `#${x.map((v, i) => Math.round(v + (y[i] - v) * t).toString(16).padStart(2, "0")).join("")}`;
}
// A token as [hue°, saturation %, lightness %], for ramps that turn around it.
function inkHsl(hex) {
  const c = inkRgb(hex) || [0, 0, 0];
  const [r, g, b] = c.map((v) => v / 255);
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const l = (max + min) / 2;
  const d = max - min;
  if (d === 0) return [0, 0, l * 100];
  const s = d / (1 - Math.abs(2 * l - 1));
  const h = max === r ? ((g - b) / d) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
  return [(h * 60 + 360) % 360, s * 100, l * 100];
}

// Version-stamp the worker and all wasm fetches so a stale browser cache can
// never pair an old engine with a newer UI.
//
// The stamp is a **content hash**, not the clock. `make wasm` writes
// `pkg/build.json` with a hash over the wasm binary, its glue and the four
// app scripts, so the same bytes get the same URL and the ~2 MB engine is
// served from the HTTP cache across reloads — and re-fetched exactly when it
// changed. `Date.now()` defeated that cache on every single reload. Served
// straight from the repo with no build there is no stamp, and the clock keeps
// today's behaviour: correct, and never cached. The stamp file itself is
// fetched with `no-cache` (revalidate, not bypass) so a new build is noticed.
// A module script may await at top level; nothing above this line needs the
// worker.
// ---------- timing marks ----------
// What the instrument promises about time is measured where it happens:
// `performance.mark("auracle:<name>")` at boot start, veil down, first sound,
// pool full, PERFORM wired (perform.js), a patch opened, a pair dealt, a
// refit landed, and a move between the levels landed or a sound taken up
// (shell.js, with where the face's flight ended). `window.__aur.marks()` lists them; the film recorder writes
// them into every rehearsal's sidecar, and the budget specs read them.
const marksOnce = new Set();
function mark(name, detail, { once = false } = {}) {
  if (once && marksOnce.has(name)) return;
  marksOnce.add(name);
  try {
    performance.mark(`auracle:${name}`, detail ? { detail } : undefined);
  } catch {
    /* evidence, never load-bearing */
  }
}
mark("boot-start");

const BUILD = await (async () => {
  try {
    const r = await fetch("./pkg/build.json", { cache: "no-cache" });
    if (r.ok) {
      const j = await r.json();
      if (j && typeof j.build === "string" && /^[0-9a-f]{8,64}$/.test(j.build)) return j.build;
    }
  } catch (_) { /* no build, or no server: fall through to the clock */ }
  return String(Date.now());
})();
// The TASTE view's lengths — dot sizes, bars, whiskers — pure, so they are
// unit-tested (taste-geom.js, tests/taste-geom.test.mjs). Awaited before the
// worker exists, so no reply can arrive while it loads.
const geom = await import(`./taste-geom.js?v=${BUILD}`);
const { directionsScale, pullMark } = geom;
// Sentences built from engine facts (a generation's outcome, a prediction's
// word), pure and unit-tested (words.js, tests/words.test.mjs).
const words = await import(`./words.js?v=${BUILD}`);
const {
  count: plural, series, capital, guessLabel, forecastLine, taughtTitle, taughtSentence, kindsInLog, emptyGeneration, evolveRefusal,
  leanSentence, platformKeys, pairGuess,
  walkSaid, walkLabel, belowNote, fromLine, grownFrom, bredRatings, markWord,
  changeParts, STRUCT_SITES, SKIP_SITES, cardLine, cardDims, cardNoFace, bredLine, turnedBy, turnsItsKnobs,
  dealRule, jobEta,
} = words;
// PATCH's guess, cable levels, new patch and module sheet (patch.js), built
// on the rack below through the host it is handed (`patchView`).
const PATCH_WORDS = words;
